# hack/gen-chaos-matrix.sh — Generate the component x role matrix and the suite
# table of the chaos page from the chaos suite headers.
#
# Reads the header of every tests/e2e-chaos/*/chainsaw-test.yaml, the leading
# run of comment and blank lines, and renders two tables between the markers
#   <!-- BEGIN chaos-matrix: generated by hack/gen-chaos-matrix.sh, do not edit -->
#   <!-- END chaos-matrix -->
# of docs/reference/testing/chaos-e2e-tests.md:
#   1. the matrix: one row per component in vocabulary order, a row without a
#      suite included, and one column per role. A cell holds the entries
#      "[<suite>](#<suite>) (<kind>)", in suite order and joined by <br>,
#      or "—";
#   2. the suite table "| Suite | Scenario ID | Matrix | Budget | Random |",
#      one row per suite in name order: the suite, its scenario or "—", its
#      <component>/<role> pairs in header order, its budget
#      "failures=<N> recovery=<S>s" or "—", and the entries of the random
#      chaos catalogue it names, joined by ", ", "none", or "—" without a
#      random line.
#
# Header lines read:
#   # Chaos matrix: <component> <role> <kind>    one or more per suite
#   # Chaos scenario: SC-CHAOS-<NNN>              at most one, unique
#   # Chaos budget: failures=<N> recovery=<S>s    tests/e2e-chaos/lib/workload.sh
#                                                 validates it
#   # Chaos random: <entry>                       one per entry of
#   # Chaos random: none (<reason>)               tests/chaos-random/catalogue.yaml,
#                                                 or exactly one none line;
#                                                 tests/unit/ci/chaos_random_catalogue_test.sh
#                                                 checks the entries
#
# The vocabulary is closed:
#   components  keystone horizon glance placement barbican neutron ovn cinder
#               nova controlplane k-orc mariadb memcached rabbitmq openbao garage
#               nfs cert-manager external-secrets envoy-gateway flux
#               hypervisor-operator kvm-node-agent
#   roles       operator self database broker cache keystone backend
#   kinds       pod-kill pod-failure container-kill partition delay
#               scale-to-zero seal policy
#
# Before it writes anything it fails, naming <file>:<line> and the line where
# one exists, when no suite exists, a marker is missing, doubled or out of
# order, a suite has no matrix line, a matrix line has other than three fields
# or a value outside the vocabulary, a suite has two scenario lines, a
# scenario other than SC-CHAOS-NNN, or the scenario of another suite, or a
# random none line stands beside another random line.
#
# Usage:
#   hack/gen-chaos-matrix.sh [--check]
#
# Without --check the page is rewritten in place. With --check a fresh render
# is diffed against the page (diff -u) instead.
#
# Optional env vars (for tests):
#   CHAOS_SUITES_DIR  — the suites directory (default tests/e2e-chaos)
#   CHAOS_PAGE        — the page (default docs/reference/testing/chaos-e2e-tests.md)
#
# Exit codes:
#   0 — the page was written, or is current
#   1 — a header or the page is invalid, or (--check) the page is stale
#   2 — usage error

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
cd "${REPO_ROOT}"
export LC_ALL=C

usage() {
  echo "Usage: hack/gen-chaos-matrix.sh [--check]" >&2
}

# ---------------------------------------------------------------------------
# 1. Arguments, paths and vocabulary
# ---------------------------------------------------------------------------
CHECK=false
case "$#:${1:-}" in
  0:) ;;
  1:--check) CHECK=true ;;
  *)
    usage
    exit 2
    ;;
esac

SUITES_DIR="${CHAOS_SUITES_DIR:-tests/e2e-chaos}"
PAGE="${CHAOS_PAGE:-docs/reference/testing/chaos-e2e-tests.md}"
BEGIN_MARKER='<!-- BEGIN chaos-matrix: generated by hack/gen-chaos-matrix.sh, do not edit -->'
END_MARKER='<!-- END chaos-matrix -->'

COMPONENTS="keystone horizon glance placement barbican neutron ovn cinder nova controlplane k-orc mariadb memcached rabbitmq openbao garage nfs cert-manager external-secrets envoy-gateway flux hypervisor-operator kvm-node-agent"
ROLES="operator self database broker cache keystone backend"
KINDS="pod-kill pod-failure container-kill partition delay scale-to-zero seal policy"

# ---------------------------------------------------------------------------
# 2. The suites and the markers
# ---------------------------------------------------------------------------
shopt -s nullglob
SUITE_FILES=("${SUITES_DIR}"/*/chainsaw-test.yaml)
shopt -u nullglob
if [[ "${#SUITE_FILES[@]}" -eq 0 ]]; then
  echo "FAIL: no suite under ${SUITES_DIR}" >&2
  exit 1
fi

# marker_line <marker> — echo the number of the one line that is the marker,
# or a FAIL line and fail.
marker_line() {
  local lines
  lines="$(grep -nxF -- "$1" "${PAGE}" | cut -d: -f1 || true)"
  if [[ -z "${lines}" ]]; then
    echo "FAIL: ${PAGE}: no line \"$1\""
    return 1
  fi
  if [[ "$(wc -l <<<"${lines}" | tr -d ' ')" -gt 1 ]]; then
    echo "FAIL: ${PAGE}:$(sed -n 2p <<<"${lines}"): a second \"$1\""
    return 1
  fi
  echo "${lines}"
}

if [[ ! -f "${PAGE}" ]]; then
  echo "FAIL: ${PAGE} does not exist" >&2
  exit 1
fi
if ! begin_at="$(marker_line "${BEGIN_MARKER}")"; then
  echo "${begin_at}" >&2
  exit 1
fi
if ! end_at="$(marker_line "${END_MARKER}")"; then
  echo "${end_at}" >&2
  exit 1
fi
if [[ "${end_at}" -lt "${begin_at}" ]]; then
  echo "FAIL: ${PAGE}:${end_at}: \"${END_MARKER}\" comes before \"${BEGIN_MARKER}\"" >&2
  exit 1
fi

# ---------------------------------------------------------------------------
# 3. Read the headers and render the block
#
# One awk pass over every suite file in name order. It prints the rendered
# block, or, when a header is invalid, one FAIL line per problem and exits 1
# after the last file.
# ---------------------------------------------------------------------------
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT
BLOCK="${WORK}/block.md"

# shellcheck disable=SC2016 # an awk program, not shell
RENDER_AWK='
function problem(msg) { print "FAIL: " msg; failed = 1 }
function at(n, line) { return FILENAME ":" n ": \"" line "\"" }
function close_suite() {
  if (suite == "") return
  if (!matrix_lines[suite]) {
    if (header_end == 0) header_end = last_line + 1
    problem(prev_file ":" header_end ": the header ends here without a \"# Chaos matrix:\" line")
  }
}
BEGIN {
  ncomp = split(COMPONENTS, comp, " ")
  for (i = 1; i <= ncomp; i++) is_comp[comp[i]] = 1
  nrole = split(ROLES, role, " ")
  for (i = 1; i <= nrole; i++) is_role[role[i]] = 1
  nkind = split(KINDS, kind_list, " ")
  for (i = 1; i <= nkind; i++) is_kind[kind_list[i]] = 1
}
FNR == 1 {
  close_suite()
  suite = FILENAME
  sub(/\/chainsaw-test\.yaml$/, "", suite)
  sub(/.*\//, "", suite)
  suites[++nsuites] = suite
  in_header = 1
  header_end = 0
  prev_file = FILENAME
}
{ last_line = FNR }
in_header && $0 !~ /^#/ && $0 !~ /^[ \t]*$/ { in_header = 0; header_end = FNR }
!in_header { next }
index($0, "# Chaos matrix:") == 1 {
  rest = substr($0, length("# Chaos matrix:") + 1)
  n = split(rest, f, " ")
  if (n != 3) { problem(at(FNR, $0) ": want \"# Chaos matrix: <component> <role> <kind>\""); next }
  if (!(f[1] in is_comp)) { problem(at(FNR, $0) ": unknown component \"" f[1] "\""); next }
  if (!(f[2] in is_role)) { problem(at(FNR, $0) ": unknown role \"" f[2] "\""); next }
  if (!(f[3] in is_kind)) { problem(at(FNR, $0) ": unknown kind \"" f[3] "\""); next }
  matrix_lines[suite]++
  cell = f[1] SUBSEP f[2]
  cells[cell] = cells[cell] (cells[cell] == "" ? "" : "<br>") "[" suite "](#" suite ") (" f[3] ")"
  pair = f[1] "/" f[2]
  if (index(" " pairs[suite] " ", " " pair " ") == 0) pairs[suite] = pairs[suite] (pairs[suite] == "" ? "" : " ") pair
  next
}
index($0, "# Chaos scenario:") == 1 {
  id = substr($0, length("# Chaos scenario:") + 1)
  gsub(/^[ \t]+|[ \t]+$/, "", id)
  if (suite in scenario) { problem(at(FNR, $0) ": a second \"# Chaos scenario:\" line"); next }
  if (id !~ /^SC-CHAOS-[0-9][0-9][0-9]$/) { problem(at(FNR, $0) ": want SC-CHAOS-NNN"); next }
  if (id in owner) { problem(at(FNR, $0) ": " id " is also the scenario of " owner[id]); next }
  scenario[suite] = id
  owner[id] = suite
  next
}
/^# Chaos budget: failures=[0-9]+ recovery=[0-9]+s$/ {
  budget[suite] = substr($0, length("# Chaos budget: ") + 1)
}
index($0, "# Chaos random:") == 1 {
  entry = substr($0, length("# Chaos random:") + 1)
  gsub(/^[ \t]+|[ \t]+$/, "", entry)
  is_none = (entry ~ /^none( |$)/)
  if (is_none && (suite in random_none)) { problem(at(FNR, $0) ": a second \"# Chaos random: none\" line"); next }
  if (is_none && random_entries[suite] > 0) { problem(at(FNR, $0) ": a \"none\" line beside an entry line"); next }
  if (!is_none && (suite in random_none)) { problem(at(FNR, $0) ": an entry line beside a \"none\" line"); next }
  if (is_none) { random_none[suite] = 1; next }
  random_entries[suite]++
  random[suite] = random[suite] (random[suite] == "" ? "" : ", ") "`" entry "`"
  next
}
END {
  close_suite()
  if (failed) exit 1
  print ""
  line = "| Component |"
  sep = "| --- |"
  for (j = 1; j <= nrole; j++) { line = line " " role[j] " |"; sep = sep " --- |" }
  print line
  print sep
  for (i = 1; i <= ncomp; i++) {
    line = "| " comp[i] " |"
    for (j = 1; j <= nrole; j++) {
      c = comp[i] SUBSEP role[j]
      line = line " " (c in cells ? cells[c] : "—") " |"
    }
    print line
  }
  print ""
  print "| Suite | Scenario ID | Matrix | Budget | Random |"
  print "| --- | --- | --- | --- | --- |"
  for (i = 1; i <= nsuites; i++) {
    s = suites[i]
    n = split(pairs[s], pr, " ")
    m = ""
    for (j = 1; j <= n; j++) m = m (m == "" ? "" : ", ") "`" pr[j] "`"
    r = (s in random_none) ? "none" : (s in random ? random[s] : "—")
    print "| [" s "](#" s ") | " (s in scenario ? scenario[s] : "—") " | " m " | " (s in budget ? budget[s] : "—") " | " r " |"
  }
  print ""
}
'

if ! awk -v COMPONENTS="${COMPONENTS}" -v ROLES="${ROLES}" -v KINDS="${KINDS}" \
  "${RENDER_AWK}" "${SUITE_FILES[@]}" >"${BLOCK}"; then
  cat "${BLOCK}" >&2
  exit 1
fi

# ---------------------------------------------------------------------------
# 4. Splice the block between the markers, then write or check
# ---------------------------------------------------------------------------
RENDERED="${WORK}/page.md"
{
  sed -n "1,${begin_at}p" "${PAGE}"
  cat "${BLOCK}"
  sed -n "${end_at},\$p" "${PAGE}"
} >"${RENDERED}"

if [[ "${CHECK}" == "true" ]]; then
  if ! diff -u "${PAGE}" "${RENDERED}"; then
    echo "FAIL: ${PAGE} is stale; run make gen-chaos-matrix" >&2
    exit 1
  fi
  exit 0
fi

# cp keeps the page's mode; every check above ran before this write.
cp "${RENDERED}" "${PAGE}"
